const data = items[0].json;
const clients = Array.isArray(data) ? data : [data];
return clients.map(c => ({ json: c }));

// PLANIFICADOR SEMANAL v5 — Lee banco_bruto, planifica la semana
// imageUrl = URL actual en banco_bruto (para que OpenAI pueda descargar la imagen ahora)
// finalUrl = URL en banco_procesado (se guardara en posts despues del movimiento)
const client = $('🔀 Iterar Por Cliente').first().json;
const files = items.map(item => item.json);
const brutoUrl = `https://vtlxfpthqpqkgfdiqqwn.supabase.co/storage/v1/object/public/loopra/${client.id}/banco_bruto/`;
const procesadoUrl = `https://vtlxfpthqpqkgfdiqqwn.supabase.co/storage/v1/object/public/loopra/${client.id}/banco_procesado/`;

const imageFiles = files.filter(f => f.name && f.name !== '.emptyFolderPlaceholder' && /\.(jpg|jpeg|png|webp)$/i.test(f.name));
const videoFiles = files.filter(f => f.name && f.name !== '.emptyFolderPlaceholder' && /\.(mp4|mov|avi|webm|mkv)$/i.test(f.name));

// NUEVO: Separar las imagenes de historias (formato vertical)
const historiaFiles = imageFiles.filter(f => f.name.toLowerCase().includes('historia_'));
const postFiles = imageFiles.filter(f => !f.name.toLowerCase().includes('historia_'));

console.log(`${client.name}: ${postFiles.length} posts, ${historiaFiles.length} historias y ${videoFiles.length} videos en banco_bruto`);

if (imageFiles.length === 0 && videoFiles.length === 0) {
  console.log('Banco bruto vacio. No hay nada que planificar.');
  return [];
}

const slots = [
  { dayOffset: 1, time: '09:00:00', type: 'HISTORIA', platform: ['instagram'], label: 'Lunes manana' },
  { dayOffset: 1, time: '19:00:00', type: 'POST',     platform: ['instagram'], label: 'Lunes tarde' },
  { dayOffset: 2, time: '12:00:00', type: 'HISTORIA', platform: ['instagram'], label: 'Martes mediodia' },
  { dayOffset: 3, time: '18:00:00', type: 'POST',     platform: ['instagram'], label: 'Miercoles tarde' },
  { dayOffset: 3, time: '21:00:00', type: 'REEL',     platform: ['instagram','tiktok'], label: 'Miercoles noche' },
  { dayOffset: 4, time: '17:00:00', type: 'HISTORIA', platform: ['instagram'], label: 'Jueves tarde' },
  { dayOffset: 5, time: '20:00:00', type: 'REEL',     platform: ['instagram','tiktok'], label: 'Viernes noche' }
];

const today = new Date();
const daysUntilMonday = today.getDay() === 0 ? 1 : 8 - today.getDay();
let postIdx = 0, histIdx = 0, vidIdx = 0, batchIdx = 0;
const batch = [];

for (const slot of slots) {
  const pubDate = new Date(today);
  pubDate.setDate(today.getDate() + daysUntilMonday + (slot.dayOffset - 1));
  const dateStr = pubDate.toISOString().split('T')[0];

  if (slot.type === 'REEL') {
    if (videoFiles.length === 0) { console.log(`Slot REEL (${slot.label}) omitido: no hay videos`); continue; }
    const file = videoFiles[vidIdx % videoFiles.length]; vidIdx++;
    batch.push({ index: batchIdx++, fileName: file.name,
      imageUrl: brutoUrl + file.name,
      finalUrl: procesadoUrl + file.name,
      contentType: 'REEL', platform: slot.platform, proposedDate: dateStr,
      proposedTime: slot.time, slotLabel: slot.label });
  } else if (slot.type === 'HISTORIA') {
    const list = historiaFiles.length > 0 ? historiaFiles : imageFiles;
    if (list.length === 0) { console.log(`Slot HISTORIA omitido: no hay imagenes`); continue; }
    const file = list[histIdx % list.length]; histIdx++;
    batch.push({ index: batchIdx++, fileName: file.name,
      imageUrl: brutoUrl + file.name,
      finalUrl: procesadoUrl + file.name,
      contentType: 'HISTORIA', platform: slot.platform, proposedDate: dateStr,
      proposedTime: slot.time, slotLabel: slot.label });
  } else {
    const list = postFiles.length > 0 ? postFiles : imageFiles;
    if (list.length === 0) { console.log(`Slot POST omitido: no hay imagenes`); continue; }
    const file = list[postIdx % list.length]; postIdx++;
    batch.push({ index: batchIdx++, fileName: file.name,
      imageUrl: brutoUrl + file.name,
      finalUrl: procesadoUrl + file.name,
      contentType: 'POST', platform: slot.platform, proposedDate: dateStr,
      proposedTime: slot.time, slotLabel: slot.label });
  }
}

if (batch.length === 0) return [];
console.log(`Batch: ${batch.length} publicaciones para ${client.name}`);
return [{ json: { client, batch } }];

const raw = items[0].json;
const batch = $('⚙️ Planificar Semana').first().json.batch;
const client = $('⚙️ Planificar Semana').first().json.client;

let aiPosts;
try {
  aiPosts = JSON.parse(raw.choices[0].message.content).posts;
} catch(e) {
  throw new Error('Error parseando OpenAI: ' + e.message);
}

return aiPosts.map(aiPost => {
  const batchItem = batch[aiPost.index];
  const copyFinal = aiPost.cta ? aiPost.copy_text + '\n\n👉 ' + aiPost.cta : aiPost.copy_text;
  return {
    json: {
      client_id: client.id,
      status: 'PENDING_APPROVAL',
      content_type: aiPost.content_type,
      copy_text: copyFinal,
      hashtags: aiPost.hashtags,
      platform: batchItem.platform,
      image_url: batchItem.finalUrl,
      proposed_date: batchItem.proposedDate,
      proposed_time: batchItem.proposedTime,
      ai_analysis: { mood: aiPost.ai_mood, slot_label: batchItem.slotLabel, model: 'gpt-4o', generated_at: new Date().toISOString() }
    }
  };
});

// Preparar lista de archivos a mover (un item por archivo)
const batch = $('⚙️ Planificar Semana').first().json.batch;
const client = $('⚙️ Planificar Semana').first().json.client;
const usedFileNames = [...new Set(batch.map(b => b.fileName))];
console.log(`Preparando movimiento de ${usedFileNames.length} archivos a banco_procesado`);
return usedFileNames.map(fileName => ({
  json: {
    bucketId: 'loopra',
    sourceKey: `${client.id}/banco_bruto/${fileName}`,
    destinationKey: `${client.id}/banco_procesado/${fileName}`,
    fileName
  }
}));
